<?php else:$reports=sponsored_project_agent_reports($pdo,$u,$a);$pendingRevision=null;foreach($submissions as $existingSubmission){if((int)$existingSubmission['assignment_id']===(int)$a['id']&&(string)$existingSubmission['status']==='revision_requested'){$pendingRevision=$existingSubmission;break;}}?><div class="card"><strong>Assigned Agent: <?=h((string)$a['research_agent_name'])?></strong><div class="meta"><?=h((string)$a['project_title'])?></div><?php if($assignmentComp):?><div class="meta">Frozen compensation <?=h((string)$assignmentComp['currency'])?> <?=number_format(((int)$assignmentComp['amount_cents'])/100,2)?> · <?=h(ucwords(str_replace('_',' ',(string)$assignmentComp['status'])))?></div><?php endif?><a class="button secondary" href="/research-reports.php?agent=<?=rawurlencode((string)$a['research_agent_public_id'])?>&view=recent">Open Agent Reports</a></div><?php if($pendingRevision):?><div class="card"><span class="badge">Revision required</span><h3><?=h((string)$pendingRevision['title'])?></h3><p><?=nl2br(h((string)($pendingRevision['review_note']??'Please submit a revised deliverable.')))?></p><div class="meta">Revision <?=h((string)($pendingRevision['revision_number']??1))?> · submission <?=h((string)$pendingRevision['public_id'])?></div></div><?php endif?><h3><?= $pendingRevision?'Submit the requested revision':'Submit an Agent Report' ?></h3><?php if(!$reports):?><p class="meta">This Agent has no ready Report Runs yet.</p><?php endif?><?php foreach($reports as $r):?><form method="post" class="stack" style="margin-bottom:16px"><?=csrf_field()?><input type="hidden" name="op" value="submit_report"><input type="hidden" name="campaign_id" value="<?=h((string)$p['public_id'])?>"><input type="hidden" name="report_id" value="<?=h((string)$r['public_id'])?>"><?php if($pendingRevision):?><input type="hidden" name="supersedes_submission_id" value="<?=h((string)$pendingRevision['public_id'])?>"><?php endif?><input type="hidden" name="title" value="<?=h((string)